462:func (s *memSeries) appendable(t int64, v float64, headMaxt, minValidTime, oooTimeWindow int64) (isOOO bool, oooDelta int64, err error) {
463:	// Check if we can append in the in-order chunk.
464:	if t >= minValidTime {
465:		if s.headChunks == nil {
466:			// The series has no sample and was freshly created.
467:			return false, 0, nil
468:		}
469:		msMaxt := s.maxTime()
470:		if t > msMaxt {
471:			return false, 0, nil
472:		}
473:		if t == msMaxt {
474:			// We are allowing exact duplicates as we can encounter them in valid cases
475:			// like federation and erroring out at that time would be extremely noisy.
476:			// This only checks against the latest in-order sample.
477:			// The OOO headchunk has its own method to detect these duplicates.
478:			if s.lastHistogramValue != nil || s.lastFloatHistogramValue != nil {
479:				return false, 0, storage.NewDuplicateHistogramToFloatErr(t, v)
480:			}
481:			if math.Float64bits(s.lastValue) != math.Float64bits(v) {
482:				return false, 0, storage.NewDuplicateFloatErr(t, s.lastValue, v)
483:			}
484:			// Sample is identical (ts + value) with most current (highest ts) sample in sampleBuf.
485:			return false, 0, nil
486:		}
487:	}
488:
489:	// The sample cannot go in the in-order chunk. Check if it can go in the out-of-order chunk.
490:	if oooTimeWindow > 0 && t >= headMaxt-oooTimeWindow {
491:		return true, headMaxt - t, nil
492:	}
493:
494:	// The sample cannot go in both in-order and out-of-order chunk.
495:	if oooTimeWindow > 0 {
496:		return true, headMaxt - t, storage.ErrTooOldSample
497:	}
498:	if t < minValidTime {
499:		return false, headMaxt - t, storage.ErrOutOfBounds
500:	}
501:	return false, headMaxt - t, storage.ErrOutOfOrderSample
502:}
